870	                        <label for="name" class="required">Full Name <span>(letters and spaces only)</span></label>
871	                        <input type="text" id="name" name="name" placeholder="John Doe" required aria-required="true" aria-describedby="name-error name-hint" minlength="2" pattern="[A-Za-z\s]{2,}" autocomplete="name" spellcheck="false">
872	                        <div class="field-hint" id="name-hint">Please enter at least 2 characters</div>
