881	                        <label for="message" class="required">Message <span>(10-1000 characters)</span></label>
882	                        <textarea id="message" name="message" placeholder="Tell us what you think..." required aria-required="true" aria-describedby="message-error message-counter" minlength="10" maxlength="1000" autocomplete="off" spellcheck="true"></textarea>
883	                        <div class="field-error" id="message-error" role="alert"></div>
884	                        <div id="message-counter" class="message-counter" aria-live="polite" aria-atomic="true">0 / 1000</div>
885	                    </div>
886	                    <button type="submit" class="cta-button" id="submit-btn" aria-label="Submit contact form">Send Message</button>
887	                    <div id="form-feedback" class="form-feedback" role="status" aria-live="assertive" aria-atomic="true" tabindex="-1"></div>
