925	    <script>
926	        document.addEventListener('DOMContentLoaded', function() {
927	            document.getElementById('year').textContent = new Date().getFullYear();
928	
929	            const menuToggle = document.querySelector('.menu-toggle');
930	            const navMenu = document.getElementById('nav-menu');
931	
932	            if (menuToggle) {
933	                const isDesktop = () => window.innerWidth > 768;
934	
935	                const updateMenuVisibility = () => {
936	                    if (isDesktop()) {
937	                        navMenu.removeAttribute('hidden');
938	                        menuToggle.setAttribute('aria-expanded', 'true');
939	                    } else {
940	                        navMenu.setAttribute('hidden', '');
941	                        menuToggle.setAttribute('aria-expanded', 'false');
942	                    }
943	                };
944	
945	                const closeMenu = () => {
946	                    if (!isDesktop()) {
947	                        menuToggle.setAttribute('aria-expanded', 'false');
948	                        navMenu.setAttribute('hidden', '');
949	                        menuToggle.focus();
950	                    }
951	                };
952	
953	                updateMenuVisibility();
954	                window.addEventListener('resize', updateMenuVisibility);
955	
956	                menuToggle.addEventListener('click', function() {
957	                    if (!isDesktop()) {
958	                        const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
959	                        menuToggle.setAttribute('aria-expanded', !isExpanded);
960	                        navMenu.toggleAttribute('hidden');
961	                    }
962	                });
963	
964	                document.addEventListener('keydown', (e) => {
965	                    if (e.key === 'Escape' && menuToggle.getAttribute('aria-expanded') === 'true') {
966	                        closeMenu();
967	                    }
968	                });
969	
970	                const navLinks = navMenu.querySelectorAll('a');
971	                navLinks.forEach(link => {
972	                    link.addEventListener('click', closeMenu);
973	                });
974	            }
975	
976	            const learnMoreBtn = document.getElementById('learn-more-btn');
977	            if (learnMoreBtn) {
978	                learnMoreBtn.addEventListener('click', function() {
979	                    const getStartedSection = document.getElementById('get-started');
980	                    if (getStartedSection) {
981	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
982	                        document.getElementById('name').focus();
983	                    }
984	                });
985	            }
986	
987	            const contactForm = document.getElementById('contact-form');
988	            if (contactForm) {
989	                const showError = (field, message) => {
990	                    const fieldGroup = field.closest('.form-group');
991	                    const error = fieldGroup.querySelector('.field-error');
992	                    if (error) {
993	                        error.classList.add('show');
994	                        error.textContent = message;
995	                        error.setAttribute('role', 'alert');
996	                    }
997	                    field.setAttribute('aria-invalid', 'true');
998	                };
999	
1000	                const clearError = (field) => {
1001	                    const fieldGroup = field.closest('.form-group');
1002	                    const error = fieldGroup.querySelector('.field-error');
1003	                    if (error) {
1004	                        error.classList.remove('show');
1005	                        error.textContent = '';
1006	                    }
1007	                    field.setAttribute('aria-invalid', 'false');
1008	                };
1009	
1010	                const validateField = (field) => {
1011	                    if (!field) return false;
1012	                    const value = field.value.trim();
1013	
1014	                    if (!value) {
1015	                        const label = field.labels?.[0]?.textContent?.trim() || 'This field';
1016	                        showError(field, `${label} is required`);
1017	                        return false;
1018	                    }
1019	
1020	                    if (!field.checkValidity()) {
1021	                        let message = 'Invalid input';
1022	                        if (field.type === 'email') {
1023	                            message = 'Please enter a valid email address (e.g., name@domain.com)';
1024	                        } else if (field.id === 'name') {
1025	                            if (field.value.length < 2) {
1026	                                message = 'Name must be at least 2 characters long';
1027	                            } else {
1028	                                message = 'Name can only contain letters and spaces';
1029	                            }
1030	                        } else if (field.id === 'message') {
1031	                            if (field.value.length < 10) {
1032	                                message = `Message must be at least 10 characters (currently ${field.value.length})`;
1033	                            } else if (field.value.length > 1000) {
1034	                                message = `Message cannot exceed 1000 characters (currently ${field.value.length})`;
1035	                            } else {
1036	                                message = 'Please provide a valid message';
1037	                            }
1038	                        }
1039	                        showError(field, message);
1040	                        return false;
1041	                    }
1042	
1043	                    clearError(field);
1044	                    return true;
1045	                };
1046	
1047	                const messageField = document.getElementById('message');
1048	                const messageCounter = document.getElementById('message-counter');
1049	
1050	                const updateMessageCounter = () => {
1051	                    if (messageCounter) {
1052	                        messageCounter.textContent = `${messageField.value.length} / 1000`;
1053	                    }
1054	                };
1055	
1056	                if (messageField && messageCounter) {
1057	                    updateMessageCounter();
1058	                    messageField.addEventListener('input', updateMessageCounter);
1059	                }
1060	
1061	                const inputs = contactForm.querySelectorAll('input, textarea');
1062	                inputs.forEach(input => {
1063	                    input.addEventListener('blur', () => validateField(input));
1064	                    input.addEventListener('input', () => {
1065	                        if (input.getAttribute('aria-invalid') === 'true') {
1066	                            validateField(input);
1067	                        }
1068	                    });
1069	                });
1070	
1071	                let isSubmitting = false;
1072	
1073	                contactForm.addEventListener('submit', function(e) {
1074	                    e.preventDefault();
1075	
1076	                    if (isSubmitting) return;
1077	
1078	                    let isValid = true;
1079	                    const feedback = document.getElementById('form-feedback');
1080	                    feedback.className = 'form-feedback';
1081	                    feedback.textContent = '';
1082	
1083	                    inputs.forEach(input => {
1084	                        if (!validateField(input)) isValid = false;
1085	                    });
1086	
1087	                    if (!isValid) {
1088	                        feedback.className = 'form-feedback error';
1089	                        feedback.textContent = 'Please correct the errors above and try again.';
1090	                        feedback.setAttribute('role', 'alert');
1091	                        setTimeout(() => {
1092	                            feedback.focus();
1093	                            const firstError = contactForm.querySelector('[aria-invalid="true"]');
1094	                            if (firstError && firstError.focus) {
1095	                                firstError.focus();
1096	                            }
1097	                        }, 100);
1098	                        return;
1099	                    }
1100	
1101	                    const submitBtn = document.getElementById('submit-btn');
1102	                    isSubmitting = true;
1103	                    submitBtn.disabled = true;
1104	                    submitBtn.classList.add('loading');
1105	                    const originalHTML = submitBtn.innerHTML;
1106	                    const originalAriaLabel = submitBtn.getAttribute('aria-label');
1107	                    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>Sending...';
1108	                    submitBtn.setAttribute('aria-label', 'Sending message, please wait');
1109	
1110	                    const formData = new FormData(contactForm);
1111	                    const endpoint = contactForm.getAttribute('data-endpoint') || '/contact';
1112	                    const controller = new AbortController();
1113	                    const timeoutId = setTimeout(() => controller.abort(), 10000);
1114	
1115	                    fetch(endpoint, {
1116	                        method: 'POST',
1117	                        body: formData,
1118	                        signal: controller.signal
1119	                    })
1120	                    .then(response => {
1121	                        if (!response.ok) {
1122	                            throw new Error(`Server error: ${response.status}`);
1123	                        }
1124	                        return response;
1125	                    })
1126	                    .then(() => {
1127	                        feedback.className = 'form-feedback success';
1128	                        feedback.textContent = 'Thank you for your message! We will be in touch soon.';
1129	                        feedback.setAttribute('role', 'status');
1130	                        contactForm.reset();
1131	                        inputs.forEach(input => {
1132	                            clearError(input);
1133	                            input.setAttribute('aria-invalid', 'false');
1134	                        });
1135	                        updateMessageCounter();
1136	                    })
1137	                    .catch(error => {
1138	                        feedback.className = 'form-feedback error';
1139	                        if (error.name === 'AbortError') {
1140	                            feedback.textContent = 'Request timed out. Please try again.';
1141	                        } else if (error instanceof TypeError) {
1142	                            feedback.textContent = 'Network error. Please check your connection and try again.';
1143	                        } else {
1144	                            feedback.textContent = 'Something went wrong. Please try again later.';
1145	                            console.error('Form submission error:', error);
1146	                        }
1147	                    })
1148	                    .finally(() => {
1149	                        clearTimeout(timeoutId);
1150	                        isSubmitting = false;
1151	                        submitBtn.disabled = false;
1152	                        submitBtn.classList.remove('loading');
1153	                        submitBtn.innerHTML = originalHTML;
1154	                        if (originalAriaLabel) {
1155	                            submitBtn.setAttribute('aria-label', originalAriaLabel);
1156	                        }
1157	                        requestAnimationFrame(() => {
1158	                            feedback.scrollIntoView({ behavior: 'smooth', block: 'center' });
1159	                            feedback.focus();
1160	                        });
1161	                    });
1162	                });
1163	            }
1164	        });
1165	    </script>
